# Compute count of column 'Name' grouped by 'Name'
print(f"🔧 Computing count of 'Name' grouped by 'Name'")

# Check if columns exist and operation is valid
if 'Name' not in df.columns:
    print(f"❌ Error: Column 'Name' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Name' not in df.columns:
    print(f"❌ Error: Group by column 'Name' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Name')['Name'].count()
        elif "count" == "sum":
            result = df.groupby('Name')['Name'].sum()
        elif "count" == "avg":
            result = df.groupby('Name')['Name'].mean()
        elif "count" == "min":
            result = df.groupby('Name')['Name'].min()
        elif "count" == "max":
            result = df.groupby('Name')['Name'].max()

        print(f"✅ Count of 'Name' by 'Name':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Name', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Name', 'Name']].dtypes}")

